import{_ as i,a0 as o,w as s,s as l,ao as u,I as r,x as e,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"紅帽 CEO 對 OpenStack 收益表示樂觀 | LCTT x X-CMD","titleTemplate":false,"description":"紅帽 CEO 對 OpenStack 收益表示樂觀 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"紅帽 CEO 對 OpenStack 收益表示樂觀 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"紅帽 CEO 對 OpenStack 收益表示樂觀 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity","title":"紅帽 CEO 對 OpenStack 收益表示樂觀","tag":"201510","desc":""},"relativePath":"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity.md","filePath":"[post].md"}'),O={name:"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity.md"};function d(m,t,h,k,C,c){const n=o("Link");return s(),l("div",null,[t[13]||(t[13]=u('<h1 id="紅帽-ceo-對-openstack-收益表示樂觀" tabindex="-1">紅帽 CEO 對 OpenStack 收益表示樂觀 <a class="header-anchor" href="#紅帽-ceo-對-openstack-收益表示樂觀" aria-label="Permalink to “紅帽 CEO 對 OpenStack 收益表示樂觀”">​</a></h1><p>得益於圍繞 Linux 和雲不斷發展的平台與基礎設施技術，紅帽正在持續快速發展。紅帽宣佈在九月二十一日完成了 2016 財年第二季度的財務業績，再次超過預期。</p><p><img src="http://www.serverwatch.com/imagesvr_ce/1212/icon-redhatcloud-r.jpg" alt=""></p><p>這一季度，紅帽的收入為 5 億 4 百萬美元，和去年同比增長 13%。淨收入為 5 千 1 百萬美元，超過了 2015 財年第二季度的 4 千 7 百萬美元。</p><p>展望未來，紅帽為下一季度和全年提供了積極的目標。對於第三季度，紅帽希望指導收益能在 5億1千9百萬美元和5億2千3百萬美元之間，和去年同期相比增長 15%。</p><p>對於 2016 財年，紅帽的全年指導目標是 20億4千4百萬美元，和去年相比增長 14%。</p><p>紅帽 CFO Frank Calderoni 在電話會議上指出，紅帽最高的 30 個訂單差不多甚至超過了 1 百萬美元。其中有 4 個訂單超過 5 百萬美元，還有一個超過 1 千萬美元。</p><p>從近幾年的經驗來看，紅帽產品的交叉銷售非常成功，全部訂單中有超過 65% 的訂單包括了一個或多個紅帽應用和新興技術產品組件。</p><p>Calderoni 説 “我們希望這些技術，例如中間件、RHEL OpenStack 平台、OpenShift、雲管理和存儲能持續推動收益增長。”</p><h3 id="openstack" tabindex="-1">OpenStack <a class="header-anchor" href="#openstack" aria-label="Permalink to “OpenStack”">​</a></h3><p>在電話會議中，紅帽 CEO Jim Whitehurst 多次問到 OpenStack 的預期收入。Whitehurst 説得益於安裝程序的改進，最近發佈的 Red Hat OpenStack Platform 7.0 向前垮了一大步。</p><p>Whitehurst 提到：“在識別硬件和使用方面它做的很好，當然，這也意味着在硬件識別並正確使用它們方便還有很多工作要做。”</p><p>Whitehurst 説他已經開始注意到很多的生產應用程序開始遷移到 OpenStack 雲上來。他也警告説在產業化方面遷移到 OpenStack 大部分只是嚐鮮，還並沒有成為主流。</p><p>對於競爭對手， Whitehurst 尤其提到了微軟、惠普和 Mirantis。在他看來，很多組織仍然會使用多種操作系統，如果他們部分使用了微軟產品，會更傾向於開源方案作為替代選項。Whitehurst 説在雲方面他還沒有看到太多和惠普面對面的競爭，但和 Mirantis 則確實如此。</p><p>Whitehurst 説 “我們也有幾次勝利，客户從 Mirantis 轉到了 RHEL。”</p><hr>',16)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),p(n,{href:"http://www.serverwatch.com/server-news/red-hat-ceo-optimistic-on-openstack-revenue-opportunity.html"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.serverwatch.com/server-news/red-hat-ceo-optimistic-on-openstack-revenue-opportunity.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),p(n,{href:"http://www.serverwatch.com/author/Sean-Michael-Kerner-101580.htm"},{default:a(()=>[...t[2]||(t[2]=[e("Sean Michael Kerner",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),p(n,{href:"http://mutouxiaogui.cn/blog"},{default:a(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),p(n,{href:"https://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const w=i(O,[["render",d]]);export{T as __pageData,w as default};
